import{_ as i,o as a,c as e,a2 as t}from"./chunks/framework.BZAK_utg.js";const c=JSON.parse('{"title":"Redis缓存：分布式缓存配置与多级缓存简介","description":"","frontmatter":{"title":"Redis缓存：分布式缓存配置与多级缓存简介","date":"2023-02-19","categories":["编程语言","Java"],"tags":["Redis"],"prevTitle":"Redis缓存：缓存延迟与缓存失效","prevLink":"./Redis缓存：缓存延迟与缓存失效.html","nextTitle":"Redis分布式锁简介","nextLink":"./Redis分布式锁简介.html"},"headers":[],"relativePath":"posts/编程语言/Redis缓存：分布式缓存配置与多级缓存简介.md","filePath":"posts/编程语言/Redis缓存：分布式缓存配置与多级缓存简介.md"}'),n={name:"posts/编程语言/Redis缓存：分布式缓存配置与多级缓存简介.md"};function l(p,s,h,d,k,r){return a(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="redis缓存-分布式缓存配置与多级缓存简介" tabindex="-1">Redis缓存：分布式缓存配置与多级缓存简介 <a class="header-anchor" href="#redis缓存-分布式缓存配置与多级缓存简介" aria-label="Permalink to &quot;Redis缓存：分布式缓存配置与多级缓存简介&quot;">​</a></h1><p>分布式缓存与多级缓存可以实现服务的高性能和高可用。下面将介绍一下分布式缓存中主从集群与哨兵集群的配置，与多级缓存的基本场景。</p><h2 id="一、分布式缓存配置" tabindex="-1">一、分布式缓存配置 <a class="header-anchor" href="#一、分布式缓存配置" aria-label="Permalink to &quot;一、分布式缓存配置&quot;">​</a></h2><h3 id="一-主从集群" tabindex="-1">（一）主从集群 <a class="header-anchor" href="#一-主从集群" aria-label="Permalink to &quot;（一）主从集群&quot;">​</a></h3><p>主从集群一般由一个负责写的主节点和多个负责读的从节点组成。下面将演示在本机搭建一个三节点的主从集群，它们的端口号分别为：7001、7002、7003，其中，7001为主节点。</p><p>分别编辑三个redis配置文件，如下：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 7001.conf</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 7001</span></span></code></pre></div><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 7002.conf</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 7002</span></span></code></pre></div><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 7003.conf</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 7002</span></span></code></pre></div><p>随后逐个启动它们：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">redis-server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 7001.conf</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">redis-server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 7002.conf</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">redis-server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 7003.conf</span></span></code></pre></div><p>最后，进入任意一个节点验证它们的主从关系：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">redis-cli</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 7001</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> INFO Replication</span></span></code></pre></div><p>在控制台返回的信息可以看到，7001是master节点，它下面还有两个slave节点。主从集群不允许往从节点写入数据，本集群中7001是唯一一个可以写入数据的主节点。</p><h3 id="二-哨兵集群" tabindex="-1">（二）哨兵集群 <a class="header-anchor" href="#二-哨兵集群" aria-label="Permalink to &quot;（二）哨兵集群&quot;">​</a></h3><p>主从集群在一定程度上提升了Redis的性能，哨兵集群则在主从集群的基础上强化了Redis集群的可用性，保证Redis服务的自动故障恢复。</p><p>下面将演示在本机搭建一个三节点的哨兵集群，它们的端口号分别为：27001、27002、27003。</p><p>分别编辑三个sentinel配置文件，如下：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 27001.conf</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 27001</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sentinel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> monitor</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mymaster</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 127.0.0.1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 7001</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span></span></code></pre></div><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 27002.conf</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 27002</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sentinel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> monitor</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mymaster</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 127.0.0.1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 7001</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span></span></code></pre></div><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 27003.conf</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 27003</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sentinel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> monitor</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mymaster</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 127.0.0.1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 7001</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span></span></code></pre></div><p>随后逐个启动它们：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">redis-sentinel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 27001.conf</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">redis-sentinel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 27002.conf</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">redis-sentinel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 27003.conf</span></span></code></pre></div><p>随后，哨兵集群会监控主从集群，在主从集群某些节点挂掉后，哨兵会自动选举某一个从节点成为新的主节点，在旧的主节点恢复服务后，其会降级为从节点加入到新的主节点中。</p><p>为了验证上述规则，可以先关停7001主节点服务，监控7002与7003的日志，在等待一段时间后，通过日志可以发现，其中一台节点会成为主节点，随后重启7001，等待片刻，连接任意一台Redis，查看INFO信息，主从节点已然发生切换。</p><blockquote><p>查看redis与sentinel的配置文件，可以发现它们已经被哨兵自动修改了。</p></blockquote><h3 id="三-分片集群" tabindex="-1">（三）分片集群 <a class="header-anchor" href="#三-分片集群" aria-label="Permalink to &quot;（三）分片集群&quot;">​</a></h3><p>主从集群与哨兵集群可以很好地为提供高性能高可用的Redis服务，以满足当前大多数读多写少的应用场景。但如果写操作也很频繁，则可以考虑搭建分片集群。</p><p>分片集群中有多个主节点，通过散列插槽机制将Redis数据分布到不同的主节点。主节点相互交换心跳数据以保证健康（类似于上面的哨兵），且每个主节点都可以有从节点（类似于上面主从）。</p><p>普通应用场景使用主从集群与哨兵集群即可，此处暂时略过分片集群的配置过程，后续有需要再加上。</p><h2 id="二、多级缓存简介" tabindex="-1">二、多级缓存简介 <a class="header-anchor" href="#二、多级缓存简介" aria-label="Permalink to &quot;二、多级缓存简介&quot;">​</a></h2><p>一个请求的流程一般是：<code>用户浏览器 -&gt; Nginx -&gt; Tomcat -&gt; Redis -&gt; DB</code>。从浏览器到数据库的各个阶段都可以配置缓存，包括：浏览器缓存、Nginx缓存、Tomcat中JVM进程缓存、Redis缓存等等，它们组合在一起便是多级缓存。多级缓存可以有效提升性能，避免服务雪崩。</p><p>Redis缓存是多级缓存的重要部分，其本身的性能不成问题。但在高并发场景下，Tomcat却会成为性能桎梏，在Tomcat中访问Redis便会成为短板。与之相比，Nginx性能更好，对Redis预热数据的读操作可以提前交由基于Nginx的OpenResty执行。这样之后，一个请求的流程就变成了<code>用户浏览器 -&gt; Nginx -&gt; Redis -&gt; Tomcat -&gt; DB</code>。可以看到，与之前的流程相比，Redis相较于Tomcat提前了。这种方案解决了高并发的缓存数据高频读的问题，但同时也引入了额外的开发成本（基于Nginx的OpenResty基于lua语言），需要根据业务需求来权衡性能与开发成本。</p><p>多级缓存中的数据同步可以采用<code>Canal</code>等组件，<code>canal</code>伪装成了一个MySql从节点，来实时监控数据的变动，一旦数据库存在增删改操作，收到通知将主动更新Redis中的数据，以达到数据库与Redis的数据同步。</p><blockquote><p>参考文档</p></blockquote><ol><li><a href="https://redis.com" target="_blank" rel="noreferrer">Redis官方网站</a></li><li><a href="https://www.bilibili.com/video/BV1cr4y1671t/" target="_blank" rel="noreferrer">黑马程序员Redis入门到实战教程</a></li></ol>`,36)])])}const g=i(n,[["render",l]]);export{c as __pageData,g as default};
